# Code generated by Claude
"""One live call to test that google-genai with the pinned Gemini model accepts enum output (response_mime_type "text/x.enum") for the VLM completion check (design plan 8, D5).

    python experiments/enum_probe.py

Sends the stored eagle-camera image of the successful grip (experiments/llm_cache) with the verbatim VLM check prompt and the two allowed answers, through a throw-away cache (the project's
cache is not touched). Prints whether the call worked and the raw reply; exit 0 if the reply is exactly one of the two answers.
"""

import sys
import tempfile
from pathlib import Path

import cv2

sys.path.insert(0, str(Path(__file__).resolve().parent.parent))

import google.genai  # noqa: E402

from src.llm_gemini import GeminiCaller, LLMCache  # noqa: E402
from src.mpvi_prompts import VLM_ANSWERS, VLM_CHECK_PROMPT, fill_prompt  # noqa: E402
from src.task_config import LLM_CFG  # noqa: E402

IMAGE = Path(__file__).resolve().parent / "llm_cache" / "ee889017580b27204e917853d56c3f01d6f274d1ca0abbff871d81e288f89d62.png"


def main():
    img = cv2.cvtColor(cv2.imread(str(IMAGE)), cv2.COLOR_BGR2RGB)
    prompt = fill_prompt(VLM_CHECK_PROMPT, description="Grasp the beaker", completion_criteria="The beaker is held securely in the gripper")
    caller = GeminiCaller(LLM_CFG, "live", cache=LLMCache(tempfile.mkdtemp()))
    print(f"google-genai {google.genai.__version__}, model {LLM_CFG['model']}, answers {list(VLM_ANSWERS)}")
    try:
        text = caller.text_call(prompt, img, kind="vlm", version="enum-probe", choices=VLM_ANSWERS)
    except Exception as e:                                      # noqa: BLE001 - the probe reports whatever the call raised
        print(f"RESULT: the call failed: {type(e).__name__}: {e}")
        return 1
    ok = text in VLM_ANSWERS
    print(f"RESULT: the call worked, reply {text!r}, exactly one of the two answers: {ok}")
    return 0 if ok else 1


if __name__ == "__main__":
    sys.exit(main())
